import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary entry 생성 payload 입력값
 */
interface CreateEntryPayloadParams {
  /**
   * @field 생성할 entry 식별자
   */
  entryId: string;
  /**
   * @field trim 정규화할 entry 이름
   */
  name: string;
  /**
   * @field entry에 연결할 tag 목록
   */
  tags: string[];
  /**
   * @field entry 활성화 여부
   */
  enabled: boolean;
}

/**
 * @summary 정규화된 entry 생성 payload
 */
interface CreateEntryPayload {
  /**
   * @field 생성할 entry 식별자
   */
  entryId: string;
  /**
   * @field trim 정규화된 entry 이름
   */
  name: string;
  /**
   * @field entry에 연결할 tag 목록
   */
  tags: string[];
  /**
   * @field entry 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper entry 입력값을 생성 payload로 정규화
 */
export const createEntryPayload = (
  params: CreateEntryPayloadParams,
): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = params;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
